from pathlib import Path
import json
root=Path(__file__).resolve().parent; out=root/'research/outputs/sapa_wellbeing_terrain_explorer'; data=json.loads((out/'wellbeing_surface_bundle.json').read_text())
html='''<!doctype html><html><head><meta charset="utf-8"><title>SAPA Human Wellbeing Terrain Explorer</title><script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script><style>body{font-family:system-ui;margin:20px;color:#18202a}h1{margin-bottom:4px}.note{background:#eef5f7;padding:10px;border-left:4px solid #2b7280;margin:10px 0}label{margin-right:12px}select,input{margin:3px;padding:4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px}.panel{border:1px solid #d9e0e5;padding:10px;margin:8px 0}.slider{display:block}.small{font-size:12px;color:#50606d}#plot{height:640px}#status{font-weight:600}</style></head><body><h1>SAPA Human Wellbeing Terrain Explorer</h1><div class="note"><b>Human-only, aggregate terrain.</b> Empirical mode averages observed respondents in the selected X/Y region. Conditional mode shows a five-dimensional Ridge estimate with the hidden traits fixed by sliders. The surface is descriptive and cross-sectional; it is not causal, clinical, or a population-optimal map.</div><div class="panel grid"><label>X axis <select id="x"></select></label><label>Y axis <select id="y"></select></label><label>Outcome <select id="outcome"></select></label><label>Landscape <select id="mode"><option value="empirical">Observed / marginal</option><option value="conditional">Conditional 5D model</option></select></label><label>View <select id="view"><option value="3d">3D surface</option><option value="2d">2D heatmap</option></select></label></div><div id="sliders" class="panel"></div><div class="panel"><label><input type="checkbox" id="trend"> Trend plane</label><label><input type="checkbox" id="zero" checked> Zero / sample-mean plane</label><span id="status"></span></div><div id="plot"></div><div class="small">Support masking: empirical cells require N ≥ 10. Conditional sliders use standardized Big Five units; support is a five-dimensional diagnostic, not a probability. Source: SAPA V5 (23,679 respondents; aggregate terrain cohort shown in bundle).</div><script>const BUNDLE=__BUNDLE__;const axes=BUNDLE.axes;const xsel=document.getElementById('x'),ysel=document.getElementById('y'),osel=document.getElementById('outcome');axes.forEach(a=>{xsel.add(new Option(a,a));ysel.add(new Option(a,a))});xsel.value='Extraversion';ysel.value='Emotional Stability';Object.keys(BUNDLE.outcomes).sort().forEach(o=>osel.add(new Option(BUNDLE.outcomes[o].label+' (N='+BUNDLE.outcomes[o].N+')',o)));osel.value='content_balanced_ge2';const sliders=document.getElementById('sliders');const vals={};axes.forEach(a=>vals[a]=0);function renderSliders(){sliders.innerHTML='<b>Hidden-trait equalizer (conditional mode)</b>';axes.filter(a=>a!==xsel.value&&a!==ysel.value).forEach(a=>{const d=document.createElement('label');d.className='slider';d.textContent=a+' ';const i=document.createElement('input');i.type='range';i.min=-2.5;i.max=2.5;i.step=.05;i.value=vals[a];i.disabled=document.getElementById('mode').value!=='conditional';i.oninput=()=>{vals[a]=+i.value;draw()};d.append(i,document.createTextNode(' '+(+i.value).toFixed(2)+' SD'));sliders.append(d)});if(document.getElementById('mode').value==='conditional'){const b=document.createElement('button');b.textContent='Reset hidden traits to mean';b.onclick=()=>{axes.forEach(a=>vals[a]=0);renderSliders();draw()};sliders.append(b)}}function draw(){const x=xsel.value,y=ysel.value,o=osel.value,m=document.getElementById('mode').value,v=document.getElementById('view').value;renderSliders();let rows=BUNDLE.grid.filter(r=>r.outcome===o&&r.x===x&&r.y===y);let X=rows.map(r=>r.x_value),Y=rows.map(r=>r.y_value),Z=rows.map(r=>m==='empirical'?r.mean:(BUNDLE.coefficients[o].intercept+axes.map(a=>BUNDLE.coefficients[o].coef[axes.indexOf(a)]*(a===x?0:a===y?0:vals[a])).reduce((s,q)=>s+q,0)+BUNDLE.coefficients[o].coef[axes.indexOf(x)]*r.x_value+BUNDLE.coefficients[o].coef[axes.indexOf(y)]*r.y_value));let ux=[...new Set(X)].sort((a,b)=>a-b),uy=[...new Set(Y)].sort((a,b)=>a-b),zmat=uy.map(yy=>ux.map(xx=>{const k=rows.find(r=>r.x_value===xx&&r.y_value===yy);return k?Z[rows.indexOf(k)]:null}));const trace=v==='3d'?{x:ux,y:uy,z:zmat,type:'surface',colorscale:'RdBu',cmin:-2,cmax:2,contours:{z:{show:false}}}:{x:ux,y:uy,z:zmat,type:'heatmap',colorscale:'RdBu',zmin:-2,zmax:2};const layout={title:(m==='conditional'?'Conditional 5D estimate':'Observed marginal mean')+' — '+o,xaxis:{title:x+' (standardized)'},yaxis:{title:y+' (standardized)'},scene:{xaxis:{title:x},yaxis:{title:y},zaxis:{title:o+' (centered)'}},margin:{l:50,r:20,t:50,b:45}};Plotly.react('plot',[trace],layout,{responsive:true});document.getElementById('status').textContent=' N='+BUNDLE.outcomes[o].N+' | '+(m==='conditional'?'model-estimated slice; hidden traits fixed':'observed sample average');}['change','input'].forEach(ev=>{[xsel,ysel,osel,document.getElementById('mode'),document.getElementById('view')].forEach(e=>e.addEventListener(ev,draw));document.getElementById('trend').addEventListener(ev,draw);document.getElementById('zero').addEventListener(ev,draw)});draw();</script></body></html>'''.replace('__BUNDLE__',json.dumps(data,separators=(',',':')))
(out/'sapa_wellbeing_terrain_explorer.html').write_text(html)
